import { AbstractStatementNode } from "./abstract-statement-node";
import { ISkipStatement } from "../strong-weak-statement";

export class SkipStatementNode extends AbstractStatementNode {
  constructor(
    statement: ISkipStatement,
    parent: AbstractStatementNode | undefined,
  ) {
    super(statement, parent);
    this.preconditionEditable.next(false)
    this.postconditionEditable.next(false)
  }
}
