/**
 * Component for the file management and navigating between the files,
 * Primarly interacts with the {@link ProjectService}, in which the state is stored
 */
@Component({
  selector: "app-project-explorer",
  imports: [
    MatTreeModule,
    MatIconModule,
    MatButtonModule,
    MatFormFieldModule,
    MatInputModule,
    MatMenuModule,
    Menubar,
    Tree,
    PrimeTemplate,
    Button,
    InputText,
    FloatLabel,
    IconField,
    InputIcon,
    Tag,
    Tooltip,
  ],
  providers: [TreeDragDropService, DialogService],
  templateUrl: "./project-explorer.component.html",
  standalone: true,
  styleUrl: "./project-explorer.component.css",
})
export class ProjectExplorerComponent {
  projectService = inject(ProjectService);
  private router = inject(Router);
  private dialogService = inject(DialogService);
  private treeService = inject(TreeService);
  private predicateService = inject(PredicateService);
  private messageService = inject(MessageService);

  menuItems: MenuItem[] = [
    {
      label: "Save",
      icon: "pi pi-save",
      command: () => this.save(),
    },
    {
      label: "New",
      icon: "pi pi-plus",
      command: () => this.prepareAddElementToRoot(),
    },
    {
      label: "Import",
      icon: "pi pi-sign-in",
      items: [
        {
          label: "Import Project",
          icon: "pi pi-book",
          command: () => this.importProject(),
        },
        {
          label: "Import File",
          icon: "pi pi-file-import",
          command: () => this.import(),
        },
      ],
    },
    {
      label: "Export",
      icon: "pi pi-file-export",
      command: () => this.export(),
    },
  ];

  private expandedNodes: string[] = [];

  protected treeNodes: TreeNode[] = [];

  // Track the element currently being renamed (ephemeral, UI-only)
  private renamingElement: ProjectElement | null = null;
  private directoryForNewFile: ProjectElement | null = null;
  private addingToRoot = false;

  /** Inserted by Angular inject() migration for backwards compatibility */
  constructor(...args: unknown[]);

  public constructor() {
    this.projectService.dataChange.subscribe((data) => {
      this.treeNodes = this.getTreeNodes(data);
      //console.trace();
      //console.log(data);
      //console.log(this.treeNodes);
    });
  }

  private isRubbishBin(
    element: ProjectElement,
    parentContent: ProjectElement[],
  ): boolean {
    return (
      element.name === ".rubbishBin" &&
      parentContent === this.projectService.root.content
    );
  }

  protected isInRubbishBin(element: ProjectElement): boolean {
    // The rubbish bin is the special hidden directory at the root named ".rubbishBin".
    // Any element whose path is nested under that directory should be treated as
    // read-only from the explorer's point of view.
    const rubbishBinPrefix = ".rubbishBin/";
    return (
      element.path === ".rubbishBin" ||
      element.path.startsWith(rubbishBinPrefix)
    );
  }

  private getTreeNodes(content: ProjectElement[]): TreeNode<ProjectElement>[] {
    // Build nodes and inject a synthetic RenameProjectElement next to the element being renamed
    const nodes: TreeNode<ProjectElement>[] = [];

    for (const element of content) {
      // Hide most hidden elements from the root, but always show the rubbish bin
      if (
        element.name.startsWith(".") &&
        !this.isRubbishBin(element, content)
      ) {
        continue;
      }

      let icon = "pi pi-file";
      let children: TreeNode<ProjectElement>[] = [];
      const pseudoElement: ProjectElement = element;
      let type = "file";
      const expanded = this.expandedNodes.includes(element.path);
      if (element === this.renamingElement) {
        type = "rename";
      }
      if (pseudoElement instanceof ProjectDirectory) {
        // Use a trash icon for the rubbish bin directory at the root
        if (this.isRubbishBin(element, content)) {
          icon = "pi pi-trash";
        } else {
          icon = expanded ? "pi pi-folder-open" : "pi pi-folder";
        }

        if (type != "rename") {
          type = "directory";
        }
        // build children from directory content, passing the child's parent path
        children = this.getTreeNodes(pseudoElement.content);
        if (this.directoryForNewFile?.path === element.path) {
          this.directoryForNewFile = null;
          // Inject a synthetic "new file" node, but never inside the rubbish bin
          if (!this.isInRubbishBin(element)) {
            children.push({
              key: element.urn + "/new-file",
              label: "new-file",
              data: element,
              droppable: false,
              draggable: false,
              expanded: false,
              icon: "pi pi-file-edit",
              type: "fake",
              children: [],
              leaf: true,
            } as TreeNode<ProjectElement>);
          }
        }
      }
      if (pseudoElement instanceof ProjectFile) {
        switch (pseudoElement.type) {
          case "diagram":
            icon = "pi pi-sitemap";
            break;
          case "java":
          case "key":
          default:
            icon = "pi pi-code";
        }
      }

      const inRubbishBin = this.isInRubbishBin(element);

      nodes.push({
        key: element.urn,
        label: element.name,
        data: element,
        // Disallow dropping into the rubbish bin or its descendants
        droppable: type == "directory" && !inRubbishBin,
        // Elements in or under the rubbish bin should not be draggable (read-only)
        draggable: !inRubbishBin,
        expanded: expanded,
        icon: icon,
        type: type,
        children: children,
        leaf: type != "directory",
      });
    }
    if (content === this.projectService.root.content && this.addingToRoot) {
      this.addingToRoot = false;
      nodes.push({
        key: this.projectService.root.urn + "/new-file",
        label: "new-file",
        data: this.projectService.root,
        droppable: false,
        draggable: false,
        expanded: false,
        icon: "pi pi-file-edit",
        type: "fake",
        children: [],
        leaf: true,
      } as TreeNode<ProjectElement>);
    }

    // If parentPath has no children with the element we want to rename but the renamingParentPath
    // exactly matches parentPath and the renamingElement is null in the content (edge case),
    // don't inject anything. We only inject next to the matched element.

    return nodes;
  }

  /**
   * Add a new folder to the file tree
   * @param node The parent node
   * @param name The name of the new directory
   */
  public addFolder(node: ProjectElement, name: string) {
    if (!name) {
      return;
    }

    this.projectService.addDirectory(node.path, name);
  }

  /**
   * Add a new file to the file tree
   * @param node The parent node
   * @param name The name of the new file
   * @param type The type of the new file
   * @returns
   */
  public addFile(node: ProjectElement, name: string, type: string) {
    if (!name) {
      return;
    }
    this.projectService.addFile(node.path, name, type);
  }

  /**
   * Delete a project element based on the node selected by the user
   * @param node the node
   */
  public deleteElement(node: ProjectElement) {
    this.projectService.deleteElement(node);
  }

  /**
   * Open the files on clicking on them in the file tree in the corresponding editor
   * @param element The node to be opened
   */
  public navigate(element: ProjectElement) {
    if (!element) {
      return;
    }

    if (element instanceof CodeFile) {
      this.router.navigate(["editor/file/", element.path], {
        queryParamsHandling: "preserve",
      });
    }

    if (element instanceof DiagramFile) {
      this.router.navigate(["editor/diagram/", element.path], {
        queryParamsHandling: "preserve",
      });
    }
  }

  /**
   * Save the current state of the project to the backend.
   * If the projectId is not defined the user is asked to create a
   * new project
   */

  private openNewProjectDialog() {
    return this.dialogService.open(CreateProjectDialogComponent, {
      header: "Select Project",
      modal: true,
      closable: true,
    });
  }

  /**
   * Import file with the given node as a parent
   * @param node the parent node of the new file
   */
  public importElement(node: ProjectElement) {
    const element = node;
    if (!element) {
      return;
    }
    const path = element.path;
    this.dialogService.open(ImportFileDialogComponent, {
      data: { parentURN: path },
      header: "Import File",
      modal: true,
      closable: true,
    });
  }
  /**
   * Save the current state of the project to the backend.
   * If the projectId is not defined the user is asked to create a
   * new project
   */
  public save() {
    this.treeService.finalizeStatements();
    this.predicateService.exportPredicates();
    if (this.projectService.shouldCreateProject) {
      this.openNewProjectDialog()?.onClose.subscribe((created) => {
        if (created) {
          this.projectService.uploadWorkspace().then(() =>
            this.messageService.add({
              summary: "Save successful",
              severity: "success",
            }),
          );
        } else {
          this.messageService.add({
            summary: "Save cancelled",
            detail: "No project specified to save to",
            severity: "warn",
          });
        }
      });
    } else {
      this.projectService.uploadWorkspace().then(() =>
        this.messageService.add({
          summary: "Save successful",
          severity: "success",
        }),
      );
    }
  }

  /**
   * Save the project with Ctrl+S (Cmd+S on macOS) while an editor is open,
   * instead of the browser's "Save page" dialog
   * @param event the keyboard event
   */
  @HostListener("document:keydown", ["$event"])
  public onSaveShortcut(event: KeyboardEvent) {
    if (
      !(event.ctrlKey || event.metaKey) ||
      event.altKey ||
      event.shiftKey ||
      event.key.toLowerCase() !== "s" ||
      !this.router.url.startsWith("/editor")
    ) {
      return;
    }
    event.preventDefault();
    if (!event.repeat) {
      this.save();
    }
  }

  /**
   * Import file with under the root node
   */
  public import() {
    this.dialogService.open(ImportFileDialogComponent, {
      data: { parentURN: "/" },
      header: "Import File",
      modal: true,
      closable: true,
    });
  }

  /**
   * Todo: Rewrite Export with /export to allow the backend to handle the export
   */
  public export() {
    this.treeService.finalizeStatements();
    this.projectService.explorerNotify.pipe(first()).subscribe(() => {
      const structure = JSON.stringify(this.projectService.export(), null, 2);
      const blob = new Blob([structure], { type: "application/json" });
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement("a");
      a.href = url;
      a.download = this.projectService.projectName + ".json";
      a.click();
      window.URL.revokeObjectURL(url);
    });
    this.projectService.notifyEditortoSave();
  }

  /**
   * On Dropping the project element
   * @param event event emitted on dropping the node
   */
  public dropNode(event: TreeNodeDropEvent) {
    const node = event.dragNode?.data;
    let target = event.dropNode?.data;
    console.log(event);
    console.log(target);
    if (!target) {
      target = this.projectService.root;
    }

    const gotmoved = this.projectService.moveElement(node, target);
    if (!gotmoved) {
      // Todo: rename the element to fix name collision
    }
  }

  // Todo: Fix User Interface to rename a element name
  public toggleRename(node: ProjectElement) {
    const element = node;
    if (!element) return;

    if (this.renamingElement && this.renamingElement.urn === element.urn) {
      this.renamingElement = null;
      this.treeNodes = this.getTreeNodes(this.projectService.root.content);
      return;
    }

    // Start renaming this element (UI-only synthetic node)
    this.renamingElement = element;
    this.treeNodes = this.getTreeNodes(this.projectService.root.content);
  }

  /**
   * Rename element
   * @param node The node to rename
   * @param newName the new name of the node
   */
  public renameElement(node: ProjectElement, newName: string) {
    if (!newName) return;
    const element = node;
    if (!element) return;
    // Regular element rename
    this.projectService.renameElement(element, newName);
    // Clear renaming state
    this.renamingElement = null;
    this.treeNodes = this.getTreeNodes(this.projectService.root.content);
  }

  public importProject() {
    this.dialogService.open(ImportProjectDialogComponent, {
      data: { parentURN: "/" },
      header: "Import Project",
      modal: true,
      closable: true,
    });
  }

  setExpanded(node: TreeNode) {
    this.expandedNodes.push(node.data.path);

    // Preserve trash icon for the root-level rubbish bin, otherwise use folder-open
    const isRootRubbishBin =
      node.data.name === ".rubbishBin" &&
      this.projectService.root.content.includes(node.data);

    node.icon = isRootRubbishBin ? "pi pi-trash" : "pi pi-folder-open";
  }

  setCollapsed(event: TreeNodeCollapseEvent) {
    this.expandedNodes = this.expandedNodes.filter(
      (node) => node != event.node.data.path,
    );

    const isRootRubbishBin =
      event.node.data.name === ".rubbishBin" &&
      this.projectService.root.content.includes(event.node.data);

    event.node.icon = isRootRubbishBin ? "pi pi-trash" : "pi pi-folder";
  }

  protected addElementToDirectory(directory: ProjectElement, node: TreeNode) {
    this.directoryForNewFile = directory;
    this.setExpanded(node);
    this.treeNodes = this.getTreeNodes(this.projectService.root.content);
  }

  protected prepareAddElementToRoot() {
    this.addingToRoot = true;
    this.treeNodes = this.getTreeNodes(this.projectService.root.content);
  }

  protected readonly ProjectElement = ProjectElement;
}
